INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-toaimatte-1', 'sent-ex-toaimatte-1', 'en', 'Coupled with the good weather, it turned into an enjoyable trip.', 'authored'),
  ('st-ex-toaimatte-2', 'sent-ex-toaimatte-2', 'en', 'His talent, together with his effort, made him a success.', 'authored'),
  ('st-ex-toaimatte-3', 'sent-ex-toaimatte-3', 'en', 'Along with the music, the film was good.', 'authored'),
  ('st-ex-toaimatte-4', 'sent-ex-toaimatte-4', 'en', 'Coupled with the low price, it became popular.', 'authored'),
  ('st-ex-hazumini-1', 'sent-ex-hazumini-1', 'en', 'As I fell, I dropped my book.', 'authored'),
  ('st-ex-hazumini-2', 'sent-ex-hazumini-2', 'en', 'As I stood up, I banged into the desk.', 'authored'),
  ('st-ex-hazumini-3', 'sent-ex-hazumini-3', 'en', 'Running in a hurry, I went over.', 'authored'),
  ('st-ex-hazumini-4', 'sent-ex-hazumini-4', 'en', 'As I opened the door, I caught my finger in it.', 'authored'),
  ('st-ex-kiraigaaru-1', 'sent-ex-kiraigaaru-1', 'en', 'He has a tendency to see the worst in things.', 'authored'),
  ('st-ex-kiraigaaru-2', 'sent-ex-kiraigaaru-2', 'en', 'Young people have a tendency to overdo it.', 'authored'),
  ('st-ex-kiraigaaru-3', 'sent-ex-kiraigaaru-3', 'en', 'She has a tendency not to listen.', 'authored'),
  ('st-ex-kiraigaaru-4', 'sent-ex-kiraigaaru-4', 'en', 'He has a tendency to decide on his own.', 'authored'),
  ('st-ex-nitomonatte-1', 'sent-ex-nitomonatte-1', 'en', 'With economic growth, life became more comfortable.', 'authored'),
  ('st-ex-nitomonatte-2', 'sent-ex-nitomonatte-2', 'en', 'As the population rose, so did the problems.', 'authored'),
  ('st-ex-nitomonatte-3', 'sent-ex-nitomonatte-3', 'en', 'As the temperature rose, the snow melted.', 'authored'),
  ('st-ex-nitomonatte-4', 'sent-ex-nitomonatte-4', 'en', 'As you grow older, your body grows weaker.', 'authored'),
  ('st-ex-woyosoni-1', 'sent-ex-woyosoni-1', 'en', 'Ignoring his parents’ worry, he set off travelling.', 'authored'),
  ('st-ex-woyosoni-2', 'sent-ex-woyosoni-2', 'en', 'Ignoring the opposition, they pressed ahead with the plan.', 'authored'),
  ('st-ex-woyosoni-3', 'sent-ex-woyosoni-3', 'en', 'Ignoring the danger, he dived into the river.', 'authored'),
  ('st-ex-woyosoni-4', 'sent-ex-woyosoni-4', 'en', 'Ignoring his family’s hopes, he left the company.', 'authored'),
  ('st-ex-naradewa-1', 'sent-ex-naradewa-1', 'en', 'It is a dish you get only in Japan.', 'authored'),
  ('st-ex-naradewa-2', 'sent-ex-naradewa-2', 'en', 'There are pleasures you get only in winter.', 'authored'),
  ('st-ex-naradewa-3', 'sent-ex-naradewa-3', 'en', 'It is a taste you get only at that shop.', 'authored'),
  ('st-ex-naradewa-4', 'sent-ex-naradewa-4', 'en', 'It is an explanation only that teacher could give.', 'authored'),
  ('st-ex-inagarani-1', 'sent-ex-inagarani-1', 'en', 'You can do the shopping without leaving the house.', 'authored'),
  ('st-ex-inagarani-2', 'sent-ex-inagarani-2', 'en', 'You can see what the world is doing without stirring.', 'authored'),
  ('st-ex-inagarani-3', 'sent-ex-inagarani-3', 'en', 'You can watch a film without leaving your room.', 'authored'),
  ('st-ex-inagarani-4', 'sent-ex-inagarani-4', 'en', 'You can work without leaving the house.', 'authored'),
  ('st-ex-gotoki-1', 'sent-ex-gotoki-1', 'en', 'There are few people like him.', 'authored'),
  ('st-ex-gotoki-2', 'sent-ex-gotoki-2', 'en', 'Someone like me could not manage it.', 'authored'),
  ('st-ex-gotoki-3', 'sent-ex-gotoki-3', 'en', 'It is as cold as ice.', 'authored'),
  ('st-ex-gotoki-4', 'sent-ex-gotoki-4', 'en', 'It is a mountain of luggage.', 'authored'),
  ('st-ex-toshitatte-1', 'sent-ex-toshitatte-1', 'en', 'Even hurrying, I will not make it.', 'authored'),
  ('st-ex-toshitatte-2', 'sent-ex-toshitatte-2', 'en', 'Even if it is expensive, I am buying it.', 'authored'),
  ('st-ex-toshitatte-3', 'sent-ex-toshitatte-3', 'en', 'Even if I had objected, nothing would have changed.', 'authored'),
  ('st-ex-toshitatte-4', 'sent-ex-toshitatte-4', 'en', 'Even if I explained, they would not understand.', 'authored'),
  ('st-ex-nakushite-1', 'sent-ex-nakushite-1', 'en', 'Without effort there is no success.', 'authored'),
  ('st-ex-nakushite-2', 'sent-ex-nakushite-2', 'en', 'Without his help it could not have been done.', 'authored'),
  ('st-ex-nakushite-3', 'sent-ex-nakushite-3', 'en', 'It cannot be started without preparation.', 'authored'),
  ('st-ex-nakushite-4', 'sent-ex-nakushite-4', 'en', 'Without love there is no life.', 'authored')
